"""A book of orders with a cached total."""


class OrderBook:
    def __init__(self):
        self._orders = []
        self._total = None

    def add(self, order):
        """Add one order to the book."""
        self._orders.append(order)

    def total(self):
        """Return the total amount of the orders in the book."""
        if self._total is None:
            self._total = sum(x.amount for x in self._orders)
        return self._total

    def count(self):
        """Return how many orders the book holds."""
        return len(self._orders)


def group_by_customer(orders):
    """Return a dict from customer to the list of orders with that customer."""
    groups = {}
    for x in orders:
        groups.setdefault(x.customer, []).append(x)
    return groups


def customer_names(orders):
    """Return the distinct customer values, in first-seen order."""
    names = []
    for x in orders:
        if x.customer not in names:
            names.append(x.customer)
    return names

